/** Word-path labels htmlindex resolves to a multi-byte or stateful codec. */
const WORD_UNSUPPORTED: readonly string[] = [
  "big5", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "big5-hkscs", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "csunicode", // stateful or multi-byte: 256 bytes decoded to 127 runes
  "euc-jp", // stateful or multi-byte: 256 bytes decoded to 209 runes
  "euc-kr", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "gb18030", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "gb2312", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "gbk", // stateful or multi-byte: 256 bytes decoded to 193 runes
  "iso-10646-ucs-2", // stateful or multi-byte: 256 bytes decoded to 127 runes
  "iso-2022-cn", // stateful or multi-byte: 256 bytes decoded to 1 runes
  "iso-2022-jp", // stateful: sequence 1b 24 40 41 42 is not the concatenation of its bytes
  "iso-2022-kr", // stateful or multi-byte: 256 bytes decoded to 1 runes
  "ms_kanji", // stateful or multi-byte: 256 bytes decoded to 225 runes
  "shift_jis", // stateful or multi-byte: 256 bytes decoded to 225 runes
  "sjis", // stateful or multi-byte: 256 bytes decoded to 225 runes
  "unicodefffe", // stateful or multi-byte: 256 bytes decoded to 127 runes
  "utf-16", // stateful or multi-byte: 256 bytes decoded to 127 runes
  "utf-16be", // stateful or multi-byte: 256 bytes decoded to 127 runes
  "utf-16le", // stateful or multi-byte: 256 bytes decoded to 127 runes
];

const WORD_UNSUPPORTED_SET = new Set(WORD_UNSUPPORTED);

/**
 * Classifies a charset named by an RFC 2047 encoded word.
 *
 * "unresolved" here means htmlindex does not know the label, and Go's word
 * decoder then fails the word, which makes decodeWords keep the field's RAW
 * value. That is a different outcome from the body path's "unresolved", where
 * the bytes still flow through undecoded.
 */
export function classifyWordCharset(label: string): { kind: CharsetKind; table?: string } {
  const low = label.toLowerCase();
  if (WORD_UNSUPPORTED_SET.has(low)) return { kind: "unsupported" };
  const idx = WORD_SINGLE_BYTE[low];
  if (idx !== undefined) return { kind: "single-byte", table: TABLES[idx]! };
  return { kind: "unresolved" };
}

const PASSTHROUGH_SET = new Set(PASSTHROUGH);
const UNSUPPORTED_SET = new Set(UNSUPPORTED);

/**
 * Classifies a declared charset label exactly as go-message's charsetReader
 * dispatch does.
 *
 * An unlisted label is "unresolved", not "passthrough". The two produce the
 * same text — go-message leaves the body undecoded either way — but only
 * "unresolved" also raises the UnknownCharsetError that aborts a sub-part walk
 * and sends the message down the raw-body fallback. Defaulting to the quieter
 * of the two would silently disagree with Go on every message carrying an
 * exotic charset in a sub-part.
 */
export function classifyCharset(label: string): { kind: CharsetKind; table?: string } {
  const low = label.toLowerCase();
  if (PASSTHROUGH_SET.has(low)) return { kind: "passthrough" };
  if (UNSUPPORTED_SET.has(low)) return { kind: "unsupported" };
  const idx = SINGLE_BYTE[low];
  if (idx !== undefined) return { kind: "single-byte", table: TABLES[idx]! };
  return { kind: "unresolved" };
}

